function onFilterInputRender<TData extends RowData>({
  filter,
  column,
  inputId,
  onFilterUpdate,
  showValueSelector,
  setShowValueSelector,
}: {
  filter: ExtendedColumnFilter<TData>
  column: DataTableColumn<TData>
  inputId: string
  onFilterUpdate: (
    filterId: string,
    updates: Partial<Omit<ExtendedColumnFilter<TData>, "filterId">>,
  ) => void
  showValueSelector: boolean
  setShowValueSelector: (value: boolean) => void
}) {
  if (
    filter.operator === FILTER_OPERATORS.EMPTY ||
    filter.operator === FILTER_OPERATORS.NOT_EMPTY
  ) {
    return (
      <div
        id={inputId}
        role="status"
        aria-label={`${column.columnDef.meta?.label} filter is ${
          filter.operator === FILTER_OPERATORS.EMPTY ? "empty" : "not empty"
        }`}
        aria-live="polite"
        className="h-full w-16 rounded-none border bg-transparent px-1.5 py-0.5 text-muted-foreground dark:bg-input/30"
      />
    )
  }

  switch (filter.variant) {
    case FILTER_VARIANTS.TEXT:
    case FILTER_VARIANTS.NUMBER:
    case FILTER_VARIANTS.RANGE: {
      if (
        (filter.variant === FILTER_VARIANTS.RANGE &&
          filter.operator === FILTER_OPERATORS.BETWEEN) ||
        filter.operator === FILTER_OPERATORS.BETWEEN
      ) {
        return (
          <TableRangeFilter
            filter={filter}
            column={column}
            inputId={inputId}
            onFilterUpdate={onFilterUpdate}
            className="size-full max-w-28 gap-0 **:data-[slot='range-min']:border-r-0 [&_input]:rounded-none [&_input]:px-1.5"
          />
        )
      }

      const isNumber =
        filter.variant === FILTER_VARIANTS.NUMBER ||
        filter.variant === FILTER_VARIANTS.RANGE

      return (
        <Input
          id={inputId}
          type={isNumber ? FILTER_VARIANTS.NUMBER : FILTER_VARIANTS.TEXT}
          inputMode={isNumber ? "numeric" : undefined}
          placeholder={column.columnDef.meta?.placeholder ?? "Enter value..."}
          className="h-full w-24 rounded-none px-1.5"
          value={typeof filter.value === "string" ? filter.value : ""}
          onChange={event =>
            onFilterUpdate(filter.filterId, { value: event.target.value })
          }
        />
      )
    }

    case FILTER_VARIANTS.BOOLEAN: {
      const inputListboxId = `${inputId}-listbox`

      return (
        <Select
          open={showValueSelector}
          onOpenChange={setShowValueSelector}
          value={typeof filter.value === "string" ? filter.value : "true"}
          onValueChange={(value: string | null) =>
            // Base UI selects pass null on clear; Radix never does
            value && onFilterUpdate(filter.filterId, { value })
          }
          // Spread so it type-checks against Radix too: Base UI reads the
          // closed trigger's label only from `items`, Radix ignores the prop.
          {...{ items: dataTableConfig.booleanValues }}
        >
          <SelectTrigger
            id={inputId}
            aria-controls={inputListboxId}
            className="rounded-none bg-transparent px-1.5 py-0.5 [&_svg]:hidden"
          >
            <SelectValue placeholder={filter.value ? "True" : "False"} />
          </SelectTrigger>
          <SelectContent id={inputListboxId}>
            {dataTableConfig.booleanValues.map(option => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )
    }

    case FILTER_VARIANTS.SELECT:
    case FILTER_VARIANTS.MULTI_SELECT: {
      const inputListboxId = `${inputId}-listbox`

      const options = column.columnDef.meta?.options ?? []
      const selectedValues = Array.isArray(filter.value)
        ? filter.value
        : [filter.value]

      const selectedOptions = options.filter((option: Option) =>
        selectedValues.includes(option.value),
      )

      return (
        <Popover open={showValueSelector} onOpenChange={setShowValueSelector}>
          <PopoverTrigger asChild>
            <Button
              id={inputId}
              aria-controls={inputListboxId}
              variant="ghost"
              size="sm"
              className="h-full min-w-16 rounded-none border px-1.5 font-normal dark:bg-input/30"
            >
              {selectedOptions.length === 0 ? (
                filter.variant === FILTER_VARIANTS.MULTI_SELECT ? (
                  "Select options..."
                ) : (
                  "Select option..."
                )
              ) : (
                <>
                  <div className="flex items-center -space-x-2 rtl:space-x-reverse">
                    {selectedOptions.map((selectedOption: Option) =>
                      selectedOption.icon ? (
                        <div
                          key={selectedOption.value}
                          className="rounded-full border bg-background p-0.5"
                        >
                          <selectedOption.icon className="size-3.5" />
                        </div>
                      ) : null,
                    )}
                  </div>
                  <span className="truncate">
                    {selectedOptions.length > 1
                      ? `${selectedOptions.length} selected`
                      : selectedOptions[0]?.label}
                  </span>
                </>
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent
            id={inputListboxId}
            align="start"
            className="w-48 origin-[var(--radix-popover-content-transform-origin,var(--transform-origin))] p-0"
          >
            <Command>
              <CommandInput placeholder="Search options..." />
              <CommandList>
                <CommandEmpty>No options found.</CommandEmpty>
                <CommandGroup>
                  {options.map((option: Option) => (
                    <CommandItem
                      key={option.value}
                      value={option.value}
                      onSelect={() => {
                        const value =
                          filter.variant === FILTER_VARIANTS.MULTI_SELECT
                            ? selectedValues.includes(option.value)
                              ? selectedValues.filter(v => v !== option.value)
                              : [...selectedValues, option.value]
                            : option.value
                        onFilterUpdate(filter.filterId, { value })
                      }}
                    >
                      {option.icon && <option.icon />}
                      <span className="truncate">{option.label}</span>
                      {filter.variant === FILTER_VARIANTS.MULTI_SELECT && (
                        <Check
                          className={cn(
                            "ml-auto",
                            selectedValues.includes(option.value)
                              ? "opacity-100"
                              : "opacity-0",
                          )}
                        />
                      )}
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>
      )
    }

    case FILTER_VARIANTS.DATE:
    case FILTER_VARIANTS.DATE_RANGE: {
      const inputListboxId = `${inputId}-listbox`

      const dateValue = Array.isArray(filter.value)
        ? filter.value.filter(Boolean)
        : [filter.value, filter.value].filter(Boolean)

      const displayValue =
        filter.operator === FILTER_OPERATORS.BETWEEN && dateValue.length === 2
          ? `${formatDate(new Date(Number(dateValue[0])))} - ${formatDate(
              new Date(Number(dateValue[1])),
            )}`
          : dateValue[0]
            ? formatDate(new Date(Number(dateValue[0])))
            : "Pick date..."

      return (
        <Popover open={showValueSelector} onOpenChange={setShowValueSelector}>
          <PopoverTrigger asChild>
            <Button
              id={inputId}
              aria-controls={inputListboxId}
              variant="ghost"
              size="sm"
              className={cn(
                "h-full rounded-none border px-1.5 font-normal dark:bg-input/30",
                !filter.value && "text-muted-foreground",
              )}
            >
              <CalendarIcon className="size-3.5" />
              <span className="truncate">{displayValue}</span>
            </Button>
          </PopoverTrigger>
          <PopoverContent
            id={inputListboxId}
            align="start"
            className="w-auto origin-[var(--radix-popover-content-transform-origin,var(--transform-origin))] p-0"
          >
            {filter.operator === FILTER_OPERATORS.BETWEEN ? (
              <Calendar
                mode={FILTER_VARIANTS.RANGE}
                captionLayout="dropdown"
                selected={
                  dateValue.length === 2
                    ? {
                        from: new Date(Number(dateValue[0])),
                        to: new Date(Number(dateValue[1])),
                      }
                    : {
                        from: new Date(),
                        to: new Date(),
                      }
                }
                onSelect={date => {
                  onFilterUpdate(filter.filterId, {
                    value: date
                      ? [
                          (date.from?.getTime() ?? "").toString(),
                          (date.to?.getTime() ?? "").toString(),
                        ]
                      : [],
                  })
                }}
              />
            ) : (
              <Calendar
                mode="single"
                captionLayout="dropdown"
                selected={
                  dateValue[0] ? new Date(Number(dateValue[0])) : undefined
                }
                onSelect={date => {
                  onFilterUpdate(filter.filterId, {
                    value: (date?.getTime() ?? "").toString(),
                  })
                }}
              />
            )}
          </PopoverContent>
        </Popover>
      )
    }

    default:
      return null
  }
}

